UPDATE tenant_oidc_provider
SET display_name=#{displayName}, issuer_uri=#{issuerUri}, client_id=#{clientId},
    client_secret=#{clientSecret}, scopes=#{scopes}, enabled=#{enabled},
    updated_by=#{updatedBy}, version=version+1, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND provider_key=#{providerKey} AND version=#{expectedVersion}
